"""Chapter XV §2, source points 133–135 and direct/inverse point constructions 1309–1310."""
import argparse
import json
from math import cos, pi, sin
from polygon_similarity_intro import entry, house, rectangle, scaled
from rotated_circles_lines import diagram
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/homothety-centers.json'
CAP='T обозначает центр O из книги. Буква со штрихом обозначает точку с индексом 1. Отмеченные направляющие соединяют центр с соответствующими точками.'
RULE='Для гомотетии с центром O выполняется векторное равенство OX′=k·OX. Длины умножаются на |k|. Обратное построение использует 1/k.'


def homothety(title, given, k, *, inverse=False):
    first={n:(x/k,y/k) for n,(x,y) in given.items()} if inverse else given
    second=given if inverse else {n:(x*k,y*k) for n,(x,y) in given.items()}
    points={'T':(0,0),**first,**{n+'′':xy for n,xy in second.items()}}
    rays=[]
    for n in given:
        x,y=first[n]
        lo=min(0,k,1);hi=max(0,k,1)
        rays.append(((lo*x,lo*y),(hi*x,hi*y)))
    return diagram(title,points,[],rays)


def definition():
    return entry(133,None,[340,341],'Как построить образ точки при гомотетии с центром O и ненулевым коэффициентом k? Что меняется при отрицательном коэффициенте и какие случаи дают k=1 и k=−1?',
        'Центр остаётся на месте. Для точки M≠O проводим прямую OM. Если k>0, точка M′ лежит на луче OM; если k<0, она лежит на противоположном луче. В обоих случаях OM′=|k|·OM. Это равносильно векторному равенству OM′=k·OM. При k=1 зафиксирована каждая точка. При k=−1 получаем центральную симметрию, центр O — середина MM′. Обратная гомотетия с тем же центром имеет коэффициент 1/k.',
        [('Выбери луч','На первой схеме число k=2 положительно. Из T через M проведи луч и отложи удвоенную длину TM. Центр не перемещается.','Коэффициент задаёт не расстояние от исходной точки до образа, а отношение двух расстояний от центра.'),
         ('Учти отрицательный знак','Во второй схеме k=−1/2, TM=6. Выбери луч, противоположный TM, и найди расстояние TM′.','Длина не может быть отрицательной. Знак меняет луч, а расстояние умножается на модуль коэффициента.'),
         ('Проверь центральную симметрию','В третьем примере k=−1 и TM=4. Точка T лежит между M и M′. Вычисли MM′.','Обе половины MM′ равны TM, так что для полной длины нужны обе части.')],
        [homothety('Положительное увеличение',{'M':(1,2)},2),homothety('Уменьшение и противоположный луч',{'M':(6,0)},-.5),homothety('Центр — середина MM′',{'M':(0,4)},-1)],
        [('Каково расстояние TM′ при TM=6, k=−1/2?','3','6·1/2=3.'),('Какова длина MM′ при k=−1, TM=4?','8','4+4=8.')],
        RULE,'Сначала установи знак k, затем вычисли расстояние от центра до образа.',CAP,title='Гомотетия',refs=[124,131])


def below_lines():
    points={'T':(0,0),'A':(1,2),'B':(3,2),'A′':(2,4),'B′':(6,4)}
    return diagram('Прямая через центр и две параллельные прямые',points,[('T','A′'),('T','B′')],[((-1,2),(4.5,2)),((-1,4),(7,4))])


def segments():
    return diagram('Отрезок и его образ при k=−2',{'T':(0,0),'A':(1,1),'B':(4,1),'A′':(-2,-2),'B′':(-8,-2)},
                   [('A','B'),('A′','B′'),('A′','A'),('B′','B')])


def circles():
    points={'T':(0,0),'C':(2,0),'R':(2,1),'C′':(-4,0),'R′':(-4,-2)}
    rings=[]
    for (x,y),r in [((2,0),1),((-4,0),2)]:
        pts=[(x+r*cos(2*pi*i/40),y+r*sin(2*pi*i/40)) for i in range(40)]
        rings.extend(zip(pts,pts[1:]+pts[:1]))
    return diagram('Образы центра и радиуса окружности',points,[('C','R'),('C′','R′'),('C','C′')],rings)


def properties():
    return entry(134,None,[341,342],'Как при гомотетии изменяются прямая, отрезок, окружность и многоугольник? Объясни, как знак k влияет на длины.',
        'Прямая через центр переходит в себя. Прямая, не проходящая через центр, при k≠1 переходит в параллельную прямую; при k=1 она остаётся на месте. Все точки отрезка AB переходят в точки отрезка A′B′, причём A′B′=|k|·AB. Это следует из равенства векторов A′B′=k·AB и сохранения промежуточного положения. Окружность с центром C и радиусом r переходит в окружность с центром C′ и радиусом |k|r: все расстояния от C меняются в |k| раз, обратное преобразование даёт все точки образа. Соответствующие углы многоугольника равны, а стороны увеличиваются в |k| раз, поэтому многоугольники подобны.',
        [('Построй образ прямой по двум точкам','В первой модели A и B лежат на прямой вне T. Удвоив их радиус-векторы, соедини A′ и B′. Направление прямой сохранилось; прямые через T остались на тех же носителях.','Только прямая, проходящая через центр, обязана совпасть со своим образом при любом k.'),
         ('Измерь образ отрезка','Во второй модели AB=3, а k=−2. Сравни направления векторов AB и A′B′, после чего найди положительную длину образа.','Минус указывает противоположное направление вектора. В формуле длины используй |k|=2.'),
         ('Перенеси центр окружности','В третьем построении центр C переходит в C′. Радиус CR=1; k=−2. Найди диаметр окружности-образа.','Умножь радиус на модуль коэффициента и удвой уже новый радиус, чтобы получить диаметр.')],
        [below_lines(),segments(),circles()],[('Какова длина A′B′ при AB=3 и k=−2?','6','|−2|·3=6.'),('Каков диаметр образа исходной окружности радиуса 1?','4','2·(2·1)=4.')],
        RULE,'Определи образы двух точек прямой, концов отрезка или центра окружности и одной точки на ней.',CAP,title='Свойства гомотетии',refs=[131,133])


def similarity():
    return entry(135,None,[342,343,344],'Как определяется подобие произвольных фигур с помощью гомотетии и движения? Как меняется коэффициент при обратном и последовательном сравнении?',
        'Фигура F₁ подобна F, если после гомотетии F можно движением совместить полученную фигуру с F₁. Все расстояния от F к F₁ тогда умножаются на одно положительное число q=|k|. Движение сохраняет расстояния, меняя при необходимости положение, ориентацию или сторону отражения. При обратном переходе коэффициент равен 1/q. При двух последовательных подобиях с положительными коэффициентами q и p итоговый коэффициент равен pq. Это применимо к фигурам произвольной формы, а для выпуклых многоугольников совпадает с определением по углам и сторонам.',
        [('Отдели размер от положения','Первая схема содержит два подобных контура. Сначала можно изменить размер исходного, затем повернуть и перенести образ. Сравни расстояния между вершинами, даже если рёбра на экране наклонены по-разному.','Подобие произвольных фигур не требует, чтобы пары точек уже лежали на прямых через один общий центр.'),
         ('Прочитай обратный масштаб','Во второй схеме длины копии вдвое больше оригинала. Если идти обратно, коэффициент равен дроби 1/2. Назови её знаменатель.','Масштабы обратных преобразований перемножаются в 1.'),
         ('Перемножь две ступени','В третьем примере сначала все длины увеличили вдвое, затем втрое. Найди итоговый коэффициент и проверь его по основаниям исходной и конечной фигур.','Вторая ступень действует уже на изменённую длину. Коэффициенты перемножаются, а не складываются.')],
        [scaled('Подобная фигура на новом месте',house(),1.5,1.5,22),scaled('Обратный коэффициент к удвоению',rectangle(3,2),2,2,-25),scaled('Итог двух увеличений 2 и 3',house(),6,6,14)],
        [('Каков знаменатель обратного коэффициента при прямом коэффициенте 2?','2','Обратный коэффициент равен 1/2.'),('Каков общий коэффициент для 2 и 3?','6','2·3=6.')],
        'Для подобия учитывается положительный множитель расстояний. Обратный масштаб ему обратен, а последовательные масштабы перемножаются.',
        'В каждом равенстве укажи, от какой фигуры к какой сравнивается длина.','Штрихи указывают образ после изменения масштаба, поворота и переноса.',title='Подобие произвольных фигур',refs=[130,131,134])


def direct(part):
    k=2 if part=='а' else -3
    given={'A':(1,1.6),'B':(-1.2,1.6),'C':(-1.7,-.8),'D':(1.8,-.6)}
    other={'A':(3,0),'B':(-1,2),'C':(-2,-1),'D':(1,-1)}
    same=k>0
    ray='на луче OX' if same else 'на противоположном луче к OX'
    return entry(1309,part,[344],f'Даны пять точек O,A,B,C,D. Построй образы четырёх точек A,B,C,D при гомотетии с центром O и коэффициентом {k}.',
        f'Для каждой из четырёх исходных точек X проводим прямую OX. Отмечаем X₁ {ray} на расстоянии {abs(k)}·OX от центра. Так единственным образом получаются A₁,B₁,C₁,D₁. Каждый образ удовлетворяет векторному равенству OX₁={k}·OX. Если одна из взятых точек совпадёт с центром, её образом будет сам центр.',
        [('Выбери направление для каждого луча',f'От T последовательно проследи направление к A, B, C и D. Для этого коэффициента откладывай образ {ray}.','У всех четырёх построений один центр; откладывай от центра, а не от предыдущей вершины.'),
         ('Проверь отдельное расстояние',f'Во второй схеме TB=2. Найди TB′ при k={k}. Выбери правильную сторону центра независимо от проверки длины.','Длина равна модулю коэффициента, умноженному на исходную длину.'),
         ('Проверь на новом расположении',f'В третьей конфигурации TA=3. Найди TA′ при том же коэффициенте {k}. Проверь остальные три пары тем же построением.','Заново считай отрезок от центра. Точное положение точки задают одновременно луч и расстояние.')],
        [homothety('Четыре исходные точки и их образы',given,k),homothety('Проверка пары B и B′',{'A':(.5,2.2),'B':(-1.2,1.6),'C':(-1.1,-1),'D':(2,-1)},k),homothety('Новый набор точек с TA=3',other,k)],
        [('Какова длина TB′ при TB=2?',str(2*abs(k)),'Умножь 2 на модуль коэффициента.'),('Какова длина TA′ для новой конфигурации?',str(3*abs(k)),'Умножь 3 на модуль коэффициента.')],
        RULE,'Знак выбирает луч для образа, модуль задаёт длину от центра.',CAP,refs=[133])


def inverse(part):
    given={'A':(3,0),'B':(-1.8,2.4),'C':(-2,-1)}
    if part=='а':
        task='Даны центр O и конечные точки A₁,B₁,C₁ гомотетии с коэффициентом 3. Построй исходные A,B,C, из которых получаются указанные конечные точки.'
        proof='Используй обратную гомотетию с тем же центром и коэффициентом 1/3. Для каждого данного X₁ проведи луч OX₁ и на нём отложи OX=OX₁/3. Выполни это для A₁, B₁ и C₁. Прямое утроение расстояний вернёт все три исходно заданные конечные точки. В печатном начале подпункта повторены обозначения A₁ и B₁ среди искомых точек; их роль уточняет указанное в конце направление A→A₁, B→B₁, C→C₁.'
        scenes=[homothety('Найди три прообраза при k=3',given,3,inverse=True),homothety('Конечная A′ на расстоянии 6',{'A':(6,0),'B':(-3,3),'C':(-1,-3)},3,inverse=True),homothety('Новые точки с TC′=9',{'A':(2,3),'B':(-4,1),'C':(0,-9)},3,inverse=True)]
        steps=[('Определи, какие точки уже даны','Точки со штрихами соответствуют печатным A₁, B₁, C₁. Они являются результатом. Восстанови начало каждой пары.','Повторное умножение конечной длины на 3 строит ещё один образ вместо прообраза.'),
               ('Раздели расстояние','Во втором примере TA′=6. Исходную точку A ищи на том же луче в три раза ближе к T. Найди TA.','Для обратной задачи коэффициент положителен и равен 1/3.'),
               ('Проверь обратимость','В третьем примере TC′=9. Вычисли TC, затем мысленно умножь ответ на 3 и вернись к C′.','Проверка прямым преобразованием помогает не перепутать направление.')]
        checks=[('Какова TA при TA′=6?','2','6/3=2.'),('Какова TC при TC′=9?','3','9/3=3.')]
    else:
        task='Для данных центра O и конечных A₁,B₁,C₁ построй их прообразы при каждом из трёх коэффициентов: −2, 1 и 1/3.'
        proof='Правило OX=(1/k)·OX₁ является векторным. При k=−2 прообраз лежит на противоположном к OX₁ луче и вдвое ближе к O. При k=1 все три прообраза совпадают со своими конечными точками. При k=1/3 прообразы лежат на тех же лучах втрое дальше от O. Каждое построение выполняется независимо для A₁,B₁,C₁.'
        scenes=[homothety('Обратный коэффициент к −2',given,-2,inverse=True),homothety('Каждая точка совпадает со своим прообразом',given,1,inverse=True),homothety('Обратный коэффициент к 1/3',given,1/3,inverse=True)]
        steps=[('Разверни отрицательное преобразование','В первой схеме переходи от отмеченной штрихом точки к её прообразу по противоположному лучу и дели расстояние на 2.','Отрицательный знак сохраняется при обращении коэффициента: 1/(−2)=−1/2.'),
               ('Проверь тождественное преобразование','Во второй схеме k=1. Под одной меткой могут оказаться две буквы, поскольку образ и прообраз совпали. TA′=3. Чему равно TA?','Совпадение точек здесь является правильным результатом построения.'),
               ('Проверь коэффициент меньше единицы','В третьей схеме k=1/3 и TA′=3. Прообраз дальше от центра, поскольку прямое преобразование втрое сокращает расстояния. Найди TA.','В обратном направлении умножай на 3, а не на 1/3.')]
        checks=[('Какова TA при TA′=3 и k=1?','3','При k=1 точка не меняет положения.'),('Какова TA при TA′=3 и k=1/3?','9','3÷(1/3)=9.')]
    return entry(1310,part,[344],task,proof,steps,scenes,checks,RULE,'Подпиши сначала конечные точки с индексом 1. Исходные точки получаются обратным преобразованием.',CAP,refs=[133])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[definition(),properties(),similarity(),*[direct(p) for p in 'аб'],*[inverse(p) for p in 'аб']]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
